    if not candidates:
        return g
    _, orient, rail1, rail2 = max(candidates, key=lambda q: q[0])
    edge_color = rail1[2]
    if orient == 'h':
        axis_n, perp_n = w, h
        r1, r2 = rail1[:2], rail2[:2]
        markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
