    stripe_colors = {}
    marker_cells = set()
    for r, c, color in markers:
        p = c if orient == 'h' else r
        if r1[0] <= p < r1[1]:
            offset = p - r1[0]
        elif r2[0] <= p < r2[1]:
            offset = p - r2[0]
        else:
            continue
        positions = (r1[0] + offset, r2[0] + offset)
        for q in positions:
            stripe_colors[q] = color
        marker_cells.add((r, c))

    for q, color in stripe_colors.items():
        if orient == 'h':
            for c in range(1, w-1):
                g[q][c] = color
        else:
            for r in range(1, h-1):
                g[r][q] = color
