    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Determine the background as the most frequent color.
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Interior clues cast a ray toward the nearest edge. The ray is painted
    # with the clue color and the clue itself is converted to color 4.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            # Exclude colored edge objects; only interior singleton clue cells act.
            if r in (0, h-1) or c in (0, w-1):
                continue
            distances = [(r, 'up'), (h-1-r, 'down'), (c, 'left'), (w-1-c, 'right')]
            distance, direction = min(distances)
            if direction == 'up':
                for rr in range(1, r):
                    g[rr][c] = color
            elif direction == 'down':
                for rr in range(r+1, h-1):
                    g[rr][c] = color
            elif direction == 'left':
                for cc in range(1, c):
                    g[r][cc] = color
            else:
                for cc in range(c+1, w-1):
                    g[r][cc] = color
            g[r][c] = 4
    return g

