def _runs(values, background):
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        result.append((i, j, color))
        i = j
    return result

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    left_runs = _runs([grid[r][0] for r in range(h)], background)
    right_runs = _runs([grid[r][-1] for r in range(h)], background)
    pairs = [(a, b) for a in left_runs for b in right_runs
             if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]]
    if not pairs:
        return out
    left, right = max(pairs, key=lambda p: p[0][1] - p[0][0])
    rail_color = left[2]

    markers = []
    for r in range(h):
        if left[0] <= r < left[1]:
            side, offset = 0, r - left[0]
        elif right[0] <= r < right[1]:
            side, offset = 1, r - right[0]
        else:
            continue
        for c in range(1, w - 1):
            color = grid[r][c]
            if color != background and color != rail_color:
                markers.append((r, c, color, side, offset))

    for r, c, color, side, offset in markers:
        if side == 0:
            # Ray points from marker toward its own left rail.
            for cc in range(1, c):
                out[r][cc] = color
            target_row = right[0] + offset
        else:
            # Ray points from marker toward its own right rail.
            for cc in range(c + 1, w - 1):
                out[r][cc] = color
            target_row = left[0] + offset
        # The paired position on the opposite rail receives a complete stripe.
