def _runs(values, background):
    """Return contiguous non-background edge runs as (start, end, color)."""
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color = values[i]
        j = i + 1
        while j < len(values) and values[j] == color:
            j += 1
        result.append((i, j, color))
        i = j
    return result


def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    candidates = []
    # Pair matching runs on opposing vertical edges.
    left_runs = _runs([grid[r][0] for r in range(height)], background)
    right_runs = _runs([grid[r][-1] for r in range(height)], background)
    for left in left_runs:
        for right in right_runs:
            if left[2] == right[2] and left[1] - left[0] == right[1] - right[0]:
                candidates.append((left[1] - left[0], "vertical", left, right))

    # Pair matching runs on opposing horizontal edges.
    top_runs = _runs(grid[0], background)
    bottom_runs = _runs(grid[-1], background)
    for top in top_runs:
        for bottom in bottom_runs:
            if top[2] == bottom[2] and top[1] - top[0] == bottom[1] - bottom[0]:
                candidates.append((top[1] - top[0], "horizontal", top, bottom))

    if not candidates:
        return out
    _, orientation, first, second = max(candidates, key=lambda item: item[0])
    rail_color = first[2]

    markers = []
    if orientation == "vertical":
        # Markers lie on rows covered by either vertical border segment.
        for r in range(height):
            if first[0] <= r < first[1]:
                side, offset = 0, r - first[0]
            elif second[0] <= r < second[1]:
                side, offset = 1, r - second[0]
            else:
                continue
            for c in range(1, width - 1):
                color = grid[r][c]
                if color != background and color != rail_color:
                    markers.append((r, c, color, side, offset))

        # A marker sends a ray toward its own border. The corresponding
        # offset on the opposite rail receives a full perpendicular stripe.
        for r, c, color, side, offset in markers:
            if side == 0:
                for cc in range(1, c):
                    out[r][cc] = color
                target_r = second[0] + offset
                for cc in range(0, width - 1):
                    out[target_r][cc] = color
            else:
                for cc in range(c + 1, width - 1):
                    out[r][cc] = color
                target_r = first[0] + offset
                for cc in range(1, width):
                    out[target_r][cc] = color

    else:
        # Markers may occur anywhere along columns covered by either horizontal rail.
        for c in range(width):
            if first[0] <= c < first[1]:
                side, offset = 0, c - first[0]
            elif second[0] <= c < second[1]:
                side, offset = 1, c - second[0]
            else:
                continue
            for r in range(1, height - 1):
                color = grid[r][c]
                if color != background and color != rail_color:
                    markers.append((r, c, color, side, offset))

        for r, c, color, side, offset in markers:
            if side == 0:
                # Ray toward the top rail.
                for rr in range(1, r):
                    out[rr][c] = color
                target_c = second[0] + offset
                for rr in range(0, height - 1):
                    out[rr][target_c] = color
            else:
                # Ray toward the bottom rail.
                for rr in range(r + 1, height - 1):
                    out[rr][c] = color
                target_c = first[0] + offset
                for rr in range(1, height):
                    out[rr][target_c] = color

    # Markers are recolored last so crossings preserve the clue centers.
    for r, c, color, side, offset in markers:
        out[r][c] = 4
    return out


